import java.io.*;
import java.net.*;
import java.util.*;
import java.util.concurrent.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;

public class SearchIndexService {
    private final ExecutorService indexPool;
    private final ScheduledExecutorService scheduler;
    private final Path indexBasePath;
    private final Path templatePath;
    private volatile boolean shuttingDown = false;
    private final ConcurrentHashMap<String, IndexEntry> activeEntries;
    private final ContentRenderer renderer;

    public SearchIndexService(String basePath, String tmplPath) {
        this.indexBasePath = Paths.get(basePath);
        this.templatePath = Paths.get(tmplPath);
        this.indexPool = Executors.newFixedThreadPool(4);
        this.scheduler = Executors.newScheduledThreadPool(1);
        this.activeEntries = new ConcurrentHashMap<>();
        this.renderer = new ContentRenderer(templatePath);
        scheduler.scheduleAtFixedRate(this::flushPendingEntries, 5, 5, TimeUnit.SECONDS);
    }

    public void indexDocument(String docId, String title, String content, Map<String, String> metadata) {
        if (shuttingDown) throw new IllegalStateException("Service is shutting down");
        IndexEntry entry = new IndexEntry(docId, title, content, metadata);
        activeEntries.put(docId, entry);
        indexPool.submit(() -> processEntry(entry));
    }

    private void processEntry(IndexEntry entry) {
        try {
            String sanitizedTitle = sanitizeForIndex(entry.title);
            String processedContent = renderer.renderSnippet(entry.docId, entry.content, entry.metadata);
            Path entryFile = indexBasePath.resolve(entry.docId + ".idx");
            String indexData = buildIndexRecord(sanitizedTitle, processedContent, entry.metadata);
            Files.write(entryFile, indexData.getBytes(StandardCharsets.UTF_8));
        } catch (IOException e) {
            System.err.println("Failed to index: " + entry.docId);
        } finally {
            activeEntries.remove(entry.docId);
        }
    }

    private String buildIndexRecord(String title, String content, Map<String, String> metadata) {
        StringBuilder sb = new StringBuilder();
        sb.append("TITLE: ").append(title).append("\n");
        sb.append("CONTENT: ").append(content).append("\n");
        for (Map.Entry<String, String> e : metadata.entrySet()) {
            sb.append("META:").append(sanitizeForIndex(e.getKey())).append("=").append(sanitizeForIndex(e.getValue())).append("\n");
        }
        return sb.toString();
    }

    private String sanitizeForIndex(String input) {
        if (input == null) return "";
        return input.replaceAll("[<>\"'&]", "").replaceAll("[\\r\\n]", " ").trim();
    }

    private void flushPendingEntries() {
        if (activeEntries.isEmpty()) return;
        System.out.println("Pending entries: " + activeEntries.size());
    }

    public void gracefulShutdown() {
        shuttingDown = true;
        scheduler.shutdown();
        indexPool.shutdown();
        try {
            if (!indexPool.awaitTermination(30, TimeUnit.SECONDS)) {
                indexPool.shutdownNow();
            }
        } catch (InterruptedException e) {
            indexPool.shutdownNow();
            Thread.currentThread().interrupt();
        }
    }

    static class IndexEntry {
        final String docId;
        final String title;
        final String content;
        final Map<String, String> metadata;
        IndexEntry(String docId, String title, String content, Map<String, String> metadata) {
            this.docId = docId;
            this.title = title;
            this.content = content;
            this.metadata = metadata;
        }
    }

    static class ContentRenderer {
        private final Path templateDir;
        private final Map<String, String> templateCache;

        ContentRenderer(Path templateDir) {
            this.templateDir = templateDir;
            this.templateCache = new ConcurrentHashMap<>();
        }

        public String renderSnippet(String docId, String content, Map<String, String> metadata) {
            String template = loadTemplate("snippet");
            String rendered = applyTemplate(template, content, metadata);
            return rendered;
        }

        private String loadTemplate(String name) {
            return templateCache.computeIfAbsent(name, k -> {
                try {
                    Path tmpl = templateDir.resolve(k + ".tmpl");
                    return new String(Files.readAllBytes(tmpl), StandardCharsets.UTF_8);
                } catch (IOException e) {
                    return "{{content}}";
                }
            });
        }

        private String applyTemplate(String template, String content, Map<String, String> metadata) {
            String result = template.replace("{{content}}", content);
            for (Map.Entry<String, String> entry : metadata.entrySet()) {
                result = result.replace("{{" + entry.getKey() + "}}", entry.getValue());
            }
            result = resolveIncludes(result);
            return result;
        }

        private String resolveIncludes(String text) {
            // Process server-side include directives for template composition
            String result = text;
            int safety = 0;
            while (result.contains("<!--#include") && safety < 10) {
                int start = result.indexOf("<!--#include");
                int end = result.indexOf("-->", start);
                if (end == -1) break;
                String directive = result.substring(start, end + 3);
                String filePath = extractIncludePath(directive);
                String included = loadIncludeFile(filePath);
                result = result.substring(0, start) + included + result.substring(end + 3);
                safety++;
            }
            return result;
        }

        private String extractIncludePath(String directive) {
            // Extracts file="..." or virtual="..." from SSI directive
            int fileIdx = directive.indexOf("file=\"");
            if (fileIdx == -1) fileIdx = directive.indexOf("virtual=\"");
            if (fileIdx == -1) return "";
            int quote1 = directive.indexOf('"', fileIdx);
            int quote2 = directive.indexOf('"', quote1 + 1);
            if (quote1 == -1 || quote2 == -1) return "";
            return directive.substring(quote1 + 1, quote2);
        }

        private String loadIncludeFile(String filePath) {
            if (filePath.isEmpty()) return "";
            try {
                Path resolved = templateDir.resolve(filePath);
                return new String(Files.readAllBytes(resolved), StandardCharsets.UTF_8);
            } catch (IOException e) {
                return "";
            }
        }
    }

    public static void main(String[] args) {
        SearchIndexService service = new SearchIndexService("/var/index", "/var/templates");
        Runtime.getRuntime().addShutdownHook(new Thread(service::gracefulShutdown));
        Map<String, String> meta = new HashMap<>();
        meta.put("author", "system");
        service.indexDocument("doc1", "Test Document", "Hello World", meta);
    }
}
